package com.yuegang.zhihui.auth.application;
import com.yuegang.zhihui.auth.api.dto.*;import com.yuegang.zhihui.auth.domain.*;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.redis.SessionStateStore;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
public final class PasswordChangeService{private final LoginAccountRepository accounts;private final PasswordPolicy policy;private final Argon2PasswordHasher hasher;private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final SessionStateStore sessions;private final java.time.Clock clock;public PasswordChangeService(LoginAccountRepository accounts,PasswordPolicy policy,Argon2PasswordHasher hasher,DataSource dataSource,SessionStateStore sessions,java.time.Clock clock){this.accounts=accounts;this.policy=policy;this.hasher=hasher;jdbc=new JdbcTemplate(dataSource);tx=new TransactionTemplate(new DataSourceTransactionManager(dataSource));this.sessions=sessions;this.clock=clock;}public OperationResponse change(AuthenticatedAccessToken access,ChangePasswordRequest request){var account=accounts.findByAccountId(access.accountId()).orElseThrow(()->new BusinessException(ErrorCode.UNAUTHENTICATED));char[]current=request.currentPassword().toCharArray(),replacement=request.newPassword().toCharArray();try{if(!hasher.matches(current,account.passwordDigest()))throw new BusinessException(ErrorCode.UNAUTHENTICATED);if(!policy.validate(replacement).valid()||Arrays.equals(current,replacement))throw new BusinessException(ErrorCode.VALIDATION_ERROR);PasswordDigest encoded=hasher.hash(replacement);tx.executeWithoutResult(status->{if(jdbc.update("UPDATE auth_credential SET password_hash=?,password_algorithm=?,password_version=?,changed_at=NOW(6) WHERE account_id=?",encoded.hash(),encoded.algorithm(),encoded.version(),account.accountId())!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);jdbc.update("UPDATE auth_refresh_token SET revoked_at=COALESCE(revoked_at,NOW(6)),revoke_reason=COALESCE(revoke_reason,'PASSWORD_CHANGED') WHERE account_id=?",account.accountId());});sessions.revoke(access.accountId(),access.jwtId(),access.expiresAt(),clock.instant());return new OperationResponse(true);}finally{Arrays.fill(current,'\0');Arrays.fill(replacement,'\0');}}}
